/**
 * Server-side seed. Rows are generated by INSERT … SELECT generate_series
 * so a 1M-entity load does not materialize millions of JS objects.
 *
 * Tables/columns/type_ids are the ones PrepareDatabase + registerAllComponents
 * already created. Partitions and indexes exist before the first insert.
 */
import db from "../../../database";
import {
    componentTotal,
    detUuid,
    entityTotal,
    everyNth,
    idLayout,
    type IdLayout,
    type ScaleCounts,
} from "./pg-scale";

export interface SeedTypeIds {
    user: string;
    product: string;
    order: string;
    flag: string;
    item: string;
    review: string;
}

export interface SeedReport {
    entities: number;
    componentRows: number;
    insertMs: number;
    cancelled: number;
    missingScore: number;
    dirtyLegacy: number;
    reviewMin: string;
    otherMax: string;
    userMin: string;
    userMax: string;
    orderMin: string;
    orderMax: string;
    overlapped: boolean;
}

const CHUNK = 50_000;

const FUNCTIONS_SQL = `
CREATE OR REPLACE FUNCTION bench_det_uuid(n bigint) RETURNS uuid
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
  SELECT (
    substr(hex, 1, 8) || '-' ||
    substr(hex, 9, 4) || '-' ||
    '4' || substr(hex, 14, 3) || '-' ||
    'a' || substr(hex, 18, 3) || '-' ||
    substr(hex, 21, 12)
  )::uuid
  FROM (SELECT md5('bunsane-bench-v1:' || n::text) AS hex) s
$fn$;

CREATE OR REPLACE FUNCTION bench_unit(seed text) RETURNS double precision
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
  SELECT (
    (get_byte(b, 0)::bigint * 16777216) +
    (get_byte(b, 1)::bigint * 65536) +
    (get_byte(b, 2)::bigint * 256) +
    get_byte(b, 3)::bigint
  )::double precision / 4294967296.0
  FROM (SELECT decode(md5(seed), 'hex') AS b) s
$fn$;

CREATE OR REPLACE FUNCTION bench_power(u double precision, minv double precision, maxv double precision, alpha double precision)
RETURNS double precision
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
  SELECT power(
    (power(maxv, 1.0 - alpha) - power(minv, 1.0 - alpha)) * u + power(minv, 1.0 - alpha),
    1.0 / (1.0 - alpha)
  )
$fn$;
`;

type SqlClient = {
    unsafe: (query: string, values?: unknown[]) => Promise<unknown>;
    begin: <T>(fn: (tx: SqlClient) => Promise<T>) => Promise<T>;
    release: () => void | Promise<void>;
};

function asClient(value: object): SqlClient {
    return value as SqlClient;
}

async function exec(sql: SqlClient, query: string, values?: unknown[]): Promise<unknown> {
    return sql.unsafe(query, values);
}

function rowRecord(value: unknown): Record<string, unknown> | undefined {
    if (!Array.isArray(value) || value.length === 0) return undefined;
    const row = value[0];
    if (!row || typeof row !== "object") return undefined;
    return row as Record<string, unknown>;
}

function numOf(value: unknown): number {
    if (typeof value === "number" && Number.isFinite(value)) return value;
    if (typeof value === "string" && value !== "") {
        const n = Number(value);
        if (Number.isFinite(n)) return n;
    }
    throw new Error(`expected number, got ${JSON.stringify(value)}`);
}

function textOf(value: unknown): string {
    if (typeof value === "string") return value;
    if (value instanceof Date) return value.toISOString();
    if (typeof value === "number" || typeof value === "bigint") return String(value);
    throw new Error(`expected text, got ${JSON.stringify(value)}`);
}

async function installFunctions(sql: SqlClient): Promise<void> {
    for (const statement of FUNCTIONS_SQL.split(/;\s*\n\s*\n/)) {
        const body = statement.trim();
        if (!body) continue;
        await exec(sql, body.endsWith(";") ? body : `${body};`);
    }
    const rows = await exec(sql, `SELECT bench_det_uuid(1)::text AS id`);
    const got = textOf(rowRecord(rows)?.id);
    const want = detUuid(1);
    if (got !== want) {
        throw new Error(`bench_det_uuid mismatch: sql=${got} js=${want}`);
    }
}

const ENTITY_SQL = `
INSERT INTO entities (id, created_at, updated_at)
SELECT bench_det_uuid($1::bigint + i * $2::int), s.ts, s.ts
FROM generate_series($6::int, $7::int - 1) AS i
CROSS JOIN LATERAL (
  SELECT timestamptz '2024-01-01 00:00:00+00' + (
    (CASE WHEN $3::int = 1 THEN $4::int + i ELSE i * 4 + $5::int END) * interval '1 second'
  ) AS ts
) s
`;

async function insertEntities(
    tx: SqlClient,
    seqBase: number,
    stride: number,
    reviewMode: number,
    reviewOrigin: number,
    slotOffset: number,
    start: number,
    end: number,
): Promise<void> {
    await exec(tx, ENTITY_SQL, [seqBase, stride, reviewMode, reviewOrigin, slotOffset, start, end]);
}

async function inChunk(sql: SqlClient, label: string, start: number, end: number, body: (tx: SqlClient) => Promise<void>): Promise<void> {
    const t0 = performance.now();
    await sql.begin(async (tx) => {
        await exec(tx, `SET LOCAL statement_timeout = 0`);
        await exec(tx, `SET LOCAL synchronous_commit = off`);
        await body(tx);
    });
    console.log(`[pg-seed] ${label} ${start}..${end} ${Math.round(performance.now() - t0)}ms`);
}

async function forRange(total: number, body: (start: number, end: number) => Promise<void>): Promise<void> {
    for (let start = 0; start < total; start += CHUNK) {
        await body(start, Math.min(total, start + CHUNK));
    }
}

const USER_SQL = `
INSERT INTO components (id, entity_id, type_id, name, data, created_at, updated_at)
SELECT
  bench_det_uuid(($1::bigint + 1) + i * 2),
  bench_det_uuid($1::bigint + i * 2),
  $2,
  'BenchUser',
  jsonb_build_object(
    'email', x.uname || '@example.com',
    'username', x.uname,
    'status', CASE
      WHEN x.su < 0.85 THEN 'active'
      WHEN x.su < 0.97 THEN 'inactive'
      ELSE 'suspended'
    END,
    'tier', CASE
      WHEN x.tu < 0.60 THEN 'free'
      WHEN x.tu < 0.85 THEN 'basic'
      WHEN x.tu < 0.97 THEN 'premium'
      ELSE 'enterprise'
    END,
    'region', (ARRAY['us-east','us-west','eu-west','ap-south'])[1 + floor(x.ru * 4)::int],
    'orderCount', 0
  ),
  x.ts,
  x.ts
FROM generate_series($3::int, $4::int - 1) AS i
CROSS JOIN LATERAL (
  SELECT
    (ARRAY['james','mary','john','patricia','alex','emma'])[1 + (i % 6)]
      || (ARRAY['smith','johnson','williams','brown','lee','garcia'])[1 + ((i / 6) % 6)]
      || i::text AS uname,
    bench_unit('user-status:' || i::text) AS su,
    bench_unit('user-tier:' || i::text) AS tu,
    bench_unit('user-region:' || i::text) AS ru,
    timestamptz '2024-01-01 00:00:00+00' + (i * 4 * interval '1 second') AS ts
) x
`;

const PRODUCT_SQL = `
INSERT INTO components (id, entity_id, type_id, name, data, created_at, updated_at)
SELECT
  bench_det_uuid(($1::bigint + 1) + i * 2),
  bench_det_uuid($1::bigint + i * 2),
  $2,
  'BenchProduct',
  CASE
    WHEN i % 20 = 0 THEN y.base
    ELSE y.base || jsonb_build_object('score', x.score)
  END,
  x.ts,
  x.ts
FROM generate_series($3::int, $4::int - 1) AS i
CROSS JOIN LATERAL (
  SELECT
    (ARRAY['Electronics','Home','Sports','Books'])[1 + floor(bench_unit('product-cat:' || i::text) * 4)::int] AS category,
    (ARRAY['Nova','Peak','Lumen','Arbor'])[1 + floor(bench_unit('product-brand:' || i::text) * 4)::int] AS brand,
    bench_unit('product-status:' || i::text) AS su,
    floor(bench_power(bench_unit('product-price:' || i::text), 10, 1000, 1.2))::int AS price,
    round((3 + bench_unit('product-rating:' || i::text) * 2) * 10) / 10.0 AS rating,
    round(bench_unit('product-score:' || i::text) * 50) / 10.0 AS score,
    CASE
      WHEN i % 1000 = 0 THEN to_jsonb('n/a'::text)
      ELSE to_jsonb(round(bench_unit('product-legacy:' || i::text) * 50) / 10.0)
    END AS legacy,
    timestamptz '2024-01-01 00:00:00+00' + ((i * 4 + 1) * interval '1 second') AS ts
) x
CROSS JOIN LATERAL (
  SELECT jsonb_build_object(
    'sku', upper(substr(x.category, 1, 3)) || '-' || lpad(i::text, 6, '0'),
    'name', x.brand || ' ' || x.category || ' ' || i::text,
    'category', x.category,
    'status', CASE
      WHEN x.su < 0.85 THEN 'active'
      WHEN x.su < 0.95 THEN 'inactive'
      ELSE 'discontinued'
    END,
    'price', x.price,
    'rating', x.rating,
    'legacyScore', x.legacy
  ) AS base
) y
`;

const ORDER_SQL = `
INSERT INTO components (id, entity_id, type_id, name, data, created_at, updated_at)
SELECT
  bench_det_uuid($1::bigint + 1 + i * 3),
  bench_det_uuid($1::bigint + i * 3),
  $2,
  'BenchOrder',
  jsonb_build_object(
    'userId', bench_det_uuid(1 + floor(bench_unit('order-user:' || i::text) * $5::int)::int * 2)::text,
    'status', CASE
      WHEN i % 50 = 0 THEN 'cancelled'
      WHEN x.su < 0.0510204082 THEN 'pending'
      WHEN x.su < 0.1530612245 THEN 'processing'
      WHEN x.su < 0.3061224490 THEN 'shipped'
      WHEN x.su < 0.9693877551 THEN 'delivered'
      ELSE 'refunded'
    END,
    'paymentMethod', (ARRAY['card','paypal','bank','crypto'])[1 + floor(bench_unit('order-pay:' || i::text) * 4)::int],
    'total', floor(bench_power(bench_unit('order-total:' || i::text), 20, 500, 1.3))::int,
    'orderNumber', 'ORD-' || lpad(i::text, 6, '0')
  ),
  x.ts,
  x.ts
FROM generate_series($3::int, $4::int - 1) AS i
CROSS JOIN LATERAL (
  SELECT
    bench_unit('order-status:' || i::text) AS su,
    timestamptz '2024-01-01 00:00:00+00' + ((i * 4 + 2) * interval '1 second') AS ts
) x
`;

const FLAG_SQL = `
INSERT INTO components (id, entity_id, type_id, name, data, created_at, updated_at)
SELECT
  bench_det_uuid($1::bigint + 2 + i * 3),
  bench_det_uuid($1::bigint + i * 3),
  $2,
  'BenchOrderFlag',
  jsonb_build_object(
    'fulfilled', bench_unit('order-fulfilled:' || i::text) < 0.3,
    'channel', CASE WHEN bench_unit('order-channel:' || i::text) < 0.5 THEN 'web' ELSE 'store' END
  ),
  timestamptz '2024-01-01 00:00:00+00' + ((i * 4 + 2) * interval '1 second'),
  timestamptz '2024-01-01 00:00:00+00' + ((i * 4 + 2) * interval '1 second')
FROM generate_series($3::int, $4::int - 1) AS i
`;

const ITEM_SQL = `
INSERT INTO components (id, entity_id, type_id, name, data, created_at, updated_at)
SELECT
  bench_det_uuid(($1::bigint + 1) + i * 2),
  bench_det_uuid($1::bigint + i * 2),
  $2,
  'BenchOrderItem',
  jsonb_build_object(
    'orderId', bench_det_uuid($5::bigint + (i % $6::int) * 3)::text,
    'productId', bench_det_uuid($7::bigint + floor(bench_unit('item-product:' || i::text) * $8::int)::int * 2)::text,
    'status', (ARRAY['pending','fulfilled','returned','refunded'])[1 + floor(bench_unit('item-status:' || i::text) * 4)::int]
  ),
  timestamptz '2024-01-01 00:00:00+00' + ((i * 4 + 3) * interval '1 second'),
  timestamptz '2024-01-01 00:00:00+00' + ((i * 4 + 3) * interval '1 second')
FROM generate_series($3::int, $4::int - 1) AS i
`;

const REVIEW_SQL = `
INSERT INTO components (id, entity_id, type_id, name, data, created_at, updated_at)
SELECT
  bench_det_uuid(($1::bigint + 1) + i * 2),
  bench_det_uuid($1::bigint + i * 2),
  $2,
  'BenchReview',
  jsonb_build_object(
    'productId', bench_det_uuid($5::bigint + floor(bench_unit('review-product:' || i::text) * $6::int)::int * 2)::text,
    'rating', round((1 + bench_unit('review-rating:' || i::text) * 4) * 10) / 10.0
  ),
  timestamptz '2024-01-01 00:00:00+00' + (($7::int + i) * interval '1 second'),
  timestamptz '2024-01-01 00:00:00+00' + (($7::int + i) * interval '1 second')
FROM generate_series($3::int, $4::int - 1) AS i
`;

async function seedUsers(sql: SqlClient, layout: IdLayout, counts: ScaleCounts, typeId: string): Promise<void> {
    await forRange(counts.users, async (start, end) => {
        await inChunk(sql, "users", start, end, async (tx) => {
            await insertEntities(tx, layout.userEntityBase, 2, 0, 0, 0, start, end);
            await exec(tx, USER_SQL, [layout.userEntityBase, typeId, start, end]);
        });
    });
}

async function seedProducts(sql: SqlClient, layout: IdLayout, counts: ScaleCounts, typeId: string): Promise<void> {
    await forRange(counts.products, async (start, end) => {
        await inChunk(sql, "products", start, end, async (tx) => {
            await insertEntities(tx, layout.productEntityBase, 2, 0, 0, 1, start, end);
            await exec(tx, PRODUCT_SQL, [layout.productEntityBase, typeId, start, end]);
        });
    });
}

async function seedOrders(sql: SqlClient, layout: IdLayout, counts: ScaleCounts, orderType: string, flagType: string): Promise<void> {
    await forRange(counts.orders, async (start, end) => {
        await inChunk(sql, "orders", start, end, async (tx) => {
            await insertEntities(tx, layout.orderEntityBase, 3, 0, 0, 2, start, end);
            await exec(tx, ORDER_SQL, [layout.orderEntityBase, orderType, start, end, counts.users]);
            await exec(tx, FLAG_SQL, [layout.orderEntityBase, flagType, start, end]);
        });
    });
}

async function seedItems(sql: SqlClient, layout: IdLayout, counts: ScaleCounts, typeId: string): Promise<void> {
    await forRange(counts.orderItems, async (start, end) => {
        await inChunk(sql, "items", start, end, async (tx) => {
            await insertEntities(tx, layout.itemEntityBase, 2, 0, 0, 3, start, end);
            await exec(tx, ITEM_SQL, [
                layout.itemEntityBase,
                typeId,
                start,
                end,
                layout.orderEntityBase,
                counts.orders,
                layout.productEntityBase,
                counts.products,
            ]);
        });
    });
}

async function seedReviews(sql: SqlClient, layout: IdLayout, counts: ScaleCounts, typeId: string): Promise<void> {
    await forRange(counts.reviews, async (start, end) => {
        await inChunk(sql, "reviews", start, end, async (tx) => {
            await insertEntities(tx, layout.reviewEntityBase, 2, 1, layout.reviewSlotOrigin, 0, start, end);
            await exec(tx, REVIEW_SQL, [
                layout.reviewEntityBase,
                typeId,
                start,
                end,
                layout.productEntityBase,
                counts.products,
                layout.reviewSlotOrigin,
            ]);
        });
    });
}

const CHECK_SQL = `
SELECT
  (SELECT count(*)::int FROM entities) AS entities,
  (SELECT count(*)::int FROM components) AS components,
  (SELECT count(*)::int FROM components WHERE name = 'BenchOrder' AND data->>'status' = 'cancelled') AS cancelled,
  (SELECT count(*)::int FROM components WHERE name = 'BenchProduct' AND NOT (data ? 'score')) AS missing_score,
  (SELECT count(*)::int FROM components WHERE name = 'BenchProduct' AND data->>'legacyScore' = 'n/a') AS dirty,
  (SELECT min(e.created_at) FROM entities e JOIN components c ON c.entity_id = e.id AND c.name = 'BenchReview') AS review_min,
  (SELECT max(e.created_at) FROM entities e WHERE NOT EXISTS (
    SELECT 1 FROM components c WHERE c.entity_id = e.id AND c.name = 'BenchReview'
  )) AS other_max,
  (SELECT min(e.created_at) FROM entities e JOIN components c ON c.entity_id = e.id AND c.name = 'BenchUser') AS user_min,
  (SELECT max(e.created_at) FROM entities e JOIN components c ON c.entity_id = e.id AND c.name = 'BenchUser') AS user_max,
  (SELECT min(e.created_at) FROM entities e JOIN components c ON c.entity_id = e.id AND c.name = 'BenchOrder') AS order_min,
  (SELECT max(e.created_at) FROM entities e JOIN components c ON c.entity_id = e.id AND c.name = 'BenchOrder') AS order_max
`;

async function verify(sql: SqlClient, counts: ScaleCounts, insertMs: number): Promise<SeedReport> {
    const rows = await exec(sql, CHECK_SQL);
    const row = rowRecord(rows);
    if (!row) throw new Error("seed check returned no row");
    const report: SeedReport = {
        entities: numOf(row.entities),
        componentRows: numOf(row.components),
        insertMs,
        cancelled: numOf(row.cancelled),
        missingScore: numOf(row.missing_score),
        dirtyLegacy: numOf(row.dirty),
        reviewMin: textOf(row.review_min),
        otherMax: textOf(row.other_max),
        userMin: textOf(row.user_min),
        userMax: textOf(row.user_max),
        orderMin: textOf(row.order_min),
        orderMax: textOf(row.order_max),
        overlapped: false,
    };
    const wantEntities = entityTotal(counts);
    const wantComponents = componentTotal(counts);
    const wantCancelled = everyNth(counts.orders, 50);
    const wantMissing = everyNth(counts.products, 20);
    const wantDirty = everyNth(counts.products, 1000);
    const problems: string[] = [];
    if (report.entities !== wantEntities) problems.push(`entities ${report.entities} != ${wantEntities}`);
    if (report.componentRows !== wantComponents) problems.push(`components ${report.componentRows} != ${wantComponents}`);
    if (report.cancelled !== wantCancelled) problems.push(`cancelled ${report.cancelled} != ${wantCancelled}`);
    if (report.missingScore !== wantMissing) problems.push(`missing score ${report.missingScore} != ${wantMissing}`);
    if (report.dirtyLegacy !== wantDirty) problems.push(`legacy n/a ${report.dirtyLegacy} != ${wantDirty}`);
    const reviewMin = Date.parse(report.reviewMin);
    const otherMax = Date.parse(report.otherMax);
    const userMin = Date.parse(report.userMin);
    const userMax = Date.parse(report.userMax);
    const orderMin = Date.parse(report.orderMin);
    const orderMax = Date.parse(report.orderMax);
    if (!(reviewMin > otherMax)) problems.push(`reviews are not strictly newer (${report.reviewMin} <= ${report.otherMax})`);
    report.overlapped = orderMin < userMax && userMin < orderMax;
    if (!report.overlapped) problems.push("users and orders do not overlap in created_at");
    if (problems.length > 0) {
        throw new Error(`seed check failed: ${problems.join("; ")}`);
    }
    return report;
}

export async function seedDataset(counts: ScaleCounts, typeIds: SeedTypeIds): Promise<SeedReport> {
    const layout = idLayout(counts);
    const reserved = asClient(await db.reserve());
    const insertStart = performance.now();
    try {
        await installFunctions(reserved);
        console.log(
            `[pg-seed] inserting ${entityTotal(counts)} entities / ${componentTotal(counts)} components in chunks of ${CHUNK}`,
        );
        await seedUsers(reserved, layout, counts, typeIds.user);
        await seedProducts(reserved, layout, counts, typeIds.product);
        await seedOrders(reserved, layout, counts, typeIds.order, typeIds.flag);
        await seedItems(reserved, layout, counts, typeIds.item);
        await seedReviews(reserved, layout, counts, typeIds.review);
        const insertMs = Math.round(performance.now() - insertStart);
        console.log(`[pg-seed] insert done in ${insertMs}ms; analyzing`);
        const analyzeStart = performance.now();
        await exec(reserved, `ANALYZE entities`);
        await exec(reserved, `ANALYZE components`);
        console.log(`[pg-seed] analyze ${Math.round(performance.now() - analyzeStart)}ms`);
        return await verify(reserved, counts, insertMs);
    } finally {
        await reserved.release();
    }
}
